    AppLanguage.GU -> pack_gu()
    AppLanguage.UR -> pack_ur()
    AppLanguage.KN -> pack_kn()
    AppLanguage.OR -> pack_or()
    AppLanguage.ML -> pack_ml()
    AppLanguage.PA -> pack_pa()
    AppLanguage.AS -> pack_as()
    AppLanguage.MAI -> pack_mai()
    AppLanguage.SAT -> pack_sat()
    AppLanguage.KS -> pack_ks()
    AppLanguage.NE -> pack_ne()
    AppLanguage.KOK -> pack_kok()
    AppLanguage.SD -> pack_sd()
    AppLanguage.DOI -> pack_doi()
    AppLanguage.MNI -> pack_mni()
    AppLanguage.BRX -> pack_brx()
